const workspaceHandoffByState = `-- name: WorkspaceHandoffByState :one
SELECT id, state_verifier, code_verifier, origin, redirect_uri, pkce_challenge,
       purpose, session_id, operation, env_id, key_set, principal_id,
       created_at, expires_at, consumed_at, factors, factor_class
FROM workspace_handoffs WHERE state_verifier = $1
`

// Liveness is deliberately NOT in this WHERE clause, for the reason the
// credential read states: filtering here would make an unknown state cost one
// row and a consumed one zero, which is an existence oracle. The caller
// decides expiry and single-use against the row it got.
// hikyo:authn-resolution
func (q *Queries) WorkspaceHandoffByState(ctx context.Context, stateVerifier []byte) (WorkspaceHandoff, error) {
	row := q.db.QueryRow(ctx, workspaceHandoffByState, stateVerifier)
	var i WorkspaceHandoff
	err := row.Scan(
		&i.ID,
		&i.StateVerifier,
		&i.CodeVerifier,
		&i.Origin,
		&i.RedirectUri,
		&i.PkceChallenge,
		&i.Purpose,
		&i.SessionID,
		&i.Operation,
		&i.EnvID,
		&i.KeySet,
		&i.PrincipalID,
		&i.CreatedAt,
		&i.ExpiresAt,
		&i.ConsumedAt,
		&i.Factors,
		&i.FactorClass,
	)
	return i, err
}

const writeRemoteSnapshot = `-- name: WriteRemoteSnapshot :exec
INSERT INTO remote_snapshots (
    remote_id, last_attempt_at, last_outcome, observed_at, instance_identity,
    version, org_count, project_count, listing
) VALUES (
    $1, $2, $3,
    $4, $5, $6,
    $7, $8, $9
)
ON CONFLICT (remote_id) DO UPDATE SET
    last_attempt_at = excluded.last_attempt_at,
    last_outcome = excluded.last_outcome,
    observed_at = excluded.observed_at,
    instance_identity = excluded.instance_identity,
    version = excluded.version,
    org_count = excluded.org_count,
    project_count = excluded.project_count,
    listing = excluded.listing
`

type WriteRemoteSnapshotParams struct {
	RemoteID         string
	LastAttemptAt    pgtype.Timestamptz
	LastOutcome      string
	ObservedAt       pgtype.Timestamptz
	InstanceIdentity pgtype.Text
	Version          pgtype.Text
	OrgCount         pgtype.Int8
	ProjectCount     pgtype.Int8
	Listing          pgtype.Text
}

// The snapshot is upserted whole. last_attempt_at/last_outcome record the most
// recent FETCH; observed_at and the listing columns record the most recent
// SUCCESS, and a failing fetch leaves them alone - that split is the entire
// freshness model, and it is why a failure writes through the second statement
// rather than this one.
// hikyo:instance-scoped
func (q *Queries) WriteRemoteSnapshot(ctx context.Context, arg WriteRemoteSnapshotParams) error {
	_, err := q.db.Exec(ctx, writeRemoteSnapshot,
		arg.RemoteID,
		arg.LastAttemptAt,
		arg.LastOutcome,
		arg.ObservedAt,
		arg.InstanceIdentity,
		arg.Version,
		arg.OrgCount,
		arg.ProjectCount,
		arg.Listing,
	)
	return err
}
